//! rvface-models: Burn implementations of the three rvFACE networks.
//!
//! All modules are generic over `B: burn::tensor::backend::Backend`; pick
//! `burn::backend::NdArray` (CPU) or `burn::backend::Wgpu` (WebGPU) at the
//! host layer. Weights load from safetensors buffers with canonical names
//! produced by `tools/convert_weights.py` (see docs/adrs/0003).

pub mod detector;
pub mod embedder;
pub mod landmark;
mod ops;
pub mod pipeline;
pub mod weights;

pub use pipeline::{Embedder, Face, FacePipeline};

//! Depthwise-residual MobileFaceNet 68-point landmark network (Burn port).
//!
//! One parameterized implementation covers both published variants:
//!
//! - upstream `face_landmark/MobileFaceNet.py`: 64x64 gray input, ReLU,
//!   residual blocks 3/4/2, channels 32/64, GDC kernel 4x4,
//!   `Linear(512, 136, bias=True)`;
//! - cunjian/pytorch_face_landmark `models/mobilefacenet.py`: 112x112 BGR
//!   input, PReLU, residual blocks 4/6/2, channels 64/128, GDC kernel 7x7,
//!   `Linear(512, 136, bias=False)`.
//!
//! State-dict keys are identical between the two sources (`conv1.conv.weight`,
//! `conv_3.model.0.conv_dw.bn.running_mean`, `output_layer.linear.weight`,
//! ...), so the config only carries what actually differs; channel widths,
//! kernel sizes and conv groups are implied by the stored weight shapes.

use burn::tensor::activation::relu;
use burn::tensor::backend::Backend;
use burn::tensor::Tensor;

use crate::ops::{batch_norm1d, batch_norm2d, conv2d, linear_pt, prelu, relu6, TORCH_BN_EPS};
use crate::weights::{Activation, MfnDwArch, Weights, WeightsError};

/// Variant parameters of the depthwise-residual MobileFaceNet.
#[derive(Debug, Clone)]
pub struct MfnDwConfig {
    /// Non-linearity of every `Conv_block` (`relu` upstream, `prelu` cunjian).
    pub activation: Activation,
    /// `num_block` of the `conv_3` / `conv_4` / `conv_5` residual stages.
    pub residual_num_blocks: [usize; 3],
    /// GDC depthwise kernel `[kh, kw]` (input spatial size / 16).
    pub gdc_kernel: [usize; 2],
    /// Whether `output_layer.linear` has a bias.
    pub gdc_linear_bias: bool,
}

impl MfnDwConfig {
    /// Upstream `face_landmark/MobileFaceNet.py` `MobileFaceNet([64,64], 136)`.
    pub fn upstream_64() -> Self {
        Self {
            activation: Activation::Relu,
            residual_num_blocks: [3, 4, 2],
            gdc_kernel: [4, 4],
            gdc_linear_bias: true,
        }
    }

    /// cunjian/pytorch_face_landmark `MobileFaceNet([112,112], 136)`.
    pub fn cunjian_112() -> Self {
        Self {
            activation: Activation::Prelu,
            residual_num_blocks: [4, 6, 2],
            gdc_kernel: [7, 7],
            gdc_linear_bias: false,
        }
    }

    /// Builds the config from a manifest `arch` block.
    pub fn from_arch(arch: &MfnDwArch) -> Self {
        Self {
            activation: arch.activation,
            residual_num_blocks: [
                arch.residual_num_blocks.conv_3,
                arch.residual_num_blocks.conv_4,
                arch.residual_num_blocks.conv_5,
            ],
            gdc_kernel: arch.gdc_kernel,
            gdc_linear_bias: arch.gdc_linear_bias,
        }
    }
}

/// Depthwise-residual MobileFaceNet landmark regressor.
pub struct MobileFaceNetDw<B: Backend> {
    weights: Weights<B>,
    config: MfnDwConfig,
}

impl<B: Backend> MobileFaceNetDw<B> {
    /// Wraps a loaded weight store with the variant config.
    pub fn new(weights: Weights<B>, config: MfnDwConfig) -> Self {
        Self { weights, config }
    }

    fn activate(&self, x: Tensor<B, 4>, prefix: &str) -> Result<Tensor<B, 4>, WeightsError> {
        match self.config.activation {
            Activation::Relu => Ok(relu(x)),
            // No depthwise-residual checkpoint uses ReLU6; the shared
            // Activation enum carries it for the foamliu embedder flavor.
            Activation::Relu6 => Ok(relu6(x)),
            Activation::Prelu => prelu(x, &self.weights, &format!("{prefix}.prelu.weight")),
        }
    }

    /// `Conv_block`: conv (no bias) + BN + activation. Kernel size and groups
    /// come from the stored weight shape.
    fn conv_block(
        &self,
        x: Tensor<B, 4>,
        prefix: &str,
        stride: usize,
        padding: usize,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let w = &self.weights;
        let x = conv2d(
            x,
            w,
            &format!("{prefix}.conv.weight"),
            None,
            [stride, stride],
            [padding, padding],
        )?;
        let x = batch_norm2d(x, w, &format!("{prefix}.bn"), TORCH_BN_EPS)?;
        self.activate(x, prefix)
    }

    /// `Linear_block`: conv (no bias) + BN, no activation.
    fn linear_block(
        &self,
        x: Tensor<B, 4>,
        prefix: &str,
        stride: usize,
        padding: usize,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let w = &self.weights;
        let x = conv2d(
            x,
            w,
            &format!("{prefix}.conv.weight"),
            None,
            [stride, stride],
            [padding, padding],
        )?;
        batch_norm2d(x, w, &format!("{prefix}.bn"), TORCH_BN_EPS)
    }

    /// `Depth_Wise`: 1x1 expand + depthwise 3x3 (stride s) + 1x1 project,
    /// with an identity shortcut when `residual`.
    fn depth_wise(
        &self,
        x: Tensor<B, 4>,
        prefix: &str,
        stride: usize,
        residual: bool,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let short_cut = residual.then(|| x.clone());
        let x = self.conv_block(x, &format!("{prefix}.conv"), 1, 0)?;
        let x = self.conv_block(x, &format!("{prefix}.conv_dw"), stride, 1)?;
        let x = self.linear_block(x, &format!("{prefix}.project"), 1, 0)?;
        Ok(match short_cut {
            Some(s) => s + x,
            None => x,
        })
    }

    /// `Residual`: `num_block` stride-1 residual `Depth_Wise` blocks.
    fn residual(
        &self,
        mut x: Tensor<B, 4>,
        prefix: &str,
        num_block: usize,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        for i in 0..num_block {
            x = self.depth_wise(x, &format!("{prefix}.model.{i}"), 1, true)?;
        }
        Ok(x)
    }

    /// Runs the network on a normalized NCHW crop (`pixel / 255`).
    ///
    /// Returns `(landmarks, conv_features)`: `[N, 136]` normalized `[0, 1]`
    /// crop coordinates (point-major `x0,y0,x1,y1,...`) and the `[N, 512,
    /// kh, kw]` feature map ahead of the GDC head (the second element of the
    /// cunjian forward tuple; upstream computes but discards it).
    pub fn forward(&self, x: Tensor<B, 4>) -> Result<(Tensor<B, 2>, Tensor<B, 4>), WeightsError> {
        let [blocks_3, blocks_4, blocks_5] = self.config.residual_num_blocks;
        let x = self.conv_block(x, "conv1", 2, 1)?;
        let x = self.conv_block(x, "conv2_dw", 1, 1)?;
        let x = self.depth_wise(x, "conv_23", 2, false)?;
        let x = self.residual(x, "conv_3", blocks_3)?;
        let x = self.depth_wise(x, "conv_34", 2, false)?;
        let x = self.residual(x, "conv_4", blocks_4)?;
        let x = self.depth_wise(x, "conv_45", 2, false)?;
        let x = self.residual(x, "conv_5", blocks_5)?;
        let conv_features = self.conv_block(x, "conv_6_sep", 1, 0)?;

        // GDC head: global depthwise conv + flatten + linear + BN1d.
        let x = self.linear_block(conv_features.clone(), "output_layer.conv_6_dw", 1, 0)?;
        let [n, c, h, w] = x.dims();
        debug_assert_eq!([h, w], [1, 1], "GDC kernel must consume the feature map");
        let x = x.reshape([n, c * h * w]);
        let bias = if self.config.gdc_linear_bias {
            Some(self.weights.t1("output_layer.linear.bias")?)
        } else {
            None
        };
        let x = linear_pt(x, &self.weights, "output_layer.linear.weight", bias)?;
        let landmarks = batch_norm1d(x, &self.weights, "output_layer.bn", TORCH_BN_EPS)?;
        Ok((landmarks, conv_features))
    }
}

//! Face embedding networks (Burn ports).
//!
//! - [`MobileFaceNetEmbedder`]: bottleneck-style MobileFaceNet
//!   (Xiaoccer/MobileFaceNet_Pytorch `core/model.py`), 112x96 RGB input,
//!   128-d embedding.
//! - [`MobileFaceNetV2Embedder`][]: inverted-residual (MobileNetV2-style)
//!   MobileFaceNet (foamliu/MobileFaceNet `mobilefacenet.py`, Apache-2.0),
//!   112x112 RGB input, 128-d embedding.
//! - [`Irn50`]: upstream `face_feature/irn50_pytorch.py`, 128x128 RGB input,
//!   256-d embedding via a maxout over the two halves of a 512-d dense layer.
//!
//! None of the nets L2-normalize their output (upstream does not);
//! normalization happens downstream in `rvface_core::similarity`.

use burn::tensor::activation::relu;
use burn::tensor::backend::Backend;
use burn::tensor::module::{avg_pool2d, max_pool2d};
use burn::tensor::Tensor;

use crate::ops::{
    batch_norm1d, batch_norm2d, conv2d, conv2d_biased, linear_pt, prelu, relu6, TORCH_BN_EPS,
};
use crate::weights::{MfnBottleneckArch, MfnV2Arch, Weights, WeightsError};

// ---------------------------------------------------------------------------
// Bottleneck-style MobileFaceNet (Xiaoccer)
// ---------------------------------------------------------------------------

/// Variant parameters of the bottleneck-style MobileFaceNet.
#[derive(Debug, Clone)]
pub struct MfnBottleneckConfig {
    /// `[expansion, channels, num_blocks, first_stride]` rows
    /// (`Mobilefacenet_bottleneck_setting`).
    pub bottleneck_setting: Vec<[usize; 4]>,
}

impl MfnBottleneckConfig {
    /// Xiaoccer's `MobileFacenet()` defaults (112x96 input, GDC 7x6, 128-d).
    pub fn xiaoccer() -> Self {
        Self {
            bottleneck_setting: vec![
                [2, 64, 5, 2],
                [4, 128, 1, 2],
                [2, 128, 6, 1],
                [4, 128, 1, 2],
                [2, 128, 2, 1],
            ],
        }
    }

    /// Builds the config from a manifest `arch` block.
    pub fn from_arch(arch: &MfnBottleneckArch) -> Self {
        Self {
            bottleneck_setting: arch.bottleneck_setting.clone(),
        }
    }
}

/// Bottleneck-style MobileFaceNet embedder (`core/model.py MobileFacenet`).
pub struct MobileFaceNetEmbedder<B: Backend> {
    weights: Weights<B>,
    config: MfnBottleneckConfig,
}

impl<B: Backend> MobileFaceNetEmbedder<B> {
    /// Wraps a loaded weight store with the variant config.
    pub fn new(weights: Weights<B>, config: MfnBottleneckConfig) -> Self {
        Self { weights, config }
    }

    /// `ConvBlock`: conv (no bias) + BN, then PReLU unless `linear`.
    /// Kernel size and (depthwise) groups come from the weight shape.
    fn conv_block(
        &self,
        x: Tensor<B, 4>,
        prefix: &str,
        stride: usize,
        padding: usize,
        linear: bool,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let w = &self.weights;
        let x = conv2d(
            x,
            w,
            &format!("{prefix}.conv.weight"),
            None,
            [stride, stride],
            [padding, padding],
        )?;
        let x = batch_norm2d(x, w, &format!("{prefix}.bn"), TORCH_BN_EPS)?;
        if linear {
            Ok(x)
        } else {
            prelu(x, w, &format!("{prefix}.prelu.weight"))
        }
    }

    /// `Bottleneck`: 1x1 expand + BN + PReLU, depthwise 3x3 (stride s) + BN +
    /// PReLU, 1x1 project + BN; identity shortcut when `stride == 1 && inp ==
    /// oup`. Keys follow the `nn.Sequential` layout `blocks.{i}.conv.{0..7}`.
    fn bottleneck(
        &self,
        x: Tensor<B, 4>,
        idx: usize,
        stride: usize,
        connect: bool,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let w = &self.weights;
        let p = format!("blocks.{idx}.conv");
        let short_cut = connect.then(|| x.clone());
        let y = conv2d(x, w, &format!("{p}.0.weight"), None, [1, 1], [0, 0])?;
        let y = batch_norm2d(y, w, &format!("{p}.1"), TORCH_BN_EPS)?;
        let y = prelu(y, w, &format!("{p}.2.weight"))?;
        let y = conv2d(
            y,
            w,
            &format!("{p}.3.weight"),
            None,
            [stride, stride],
            [1, 1],
        )?;
        let y = batch_norm2d(y, w, &format!("{p}.4"), TORCH_BN_EPS)?;
        let y = prelu(y, w, &format!("{p}.5.weight"))?;
        let y = conv2d(y, w, &format!("{p}.6.weight"), None, [1, 1], [0, 0])?;
        let y = batch_norm2d(y, w, &format!("{p}.7"), TORCH_BN_EPS)?;
        Ok(match short_cut {
            Some(s) => s + y,
            None => y,
        })
    }

    /// Runs the network on a normalized `[N, 3, 112, 96]` crop
    /// (`(pixel - 127.5) / 128`, RGB). Returns the raw (not L2-normalized)
    /// `[N, 128]` embedding.
    pub fn forward(&self, x: Tensor<B, 4>) -> Result<Tensor<B, 2>, WeightsError> {
        let x = self.conv_block(x, "conv1", 2, 1, false)?;
        let mut x = self.conv_block(x, "dw_conv1", 1, 1, false)?;

        // `_make_layer`: expand the setting rows into a flat block sequence.
        let mut inplanes = 64usize;
        let mut idx = 0usize;
        for &[_expansion, channels, num_blocks, first_stride] in &self.config.bottleneck_setting {
            for i in 0..num_blocks {
                let stride = if i == 0 { first_stride } else { 1 };
                let connect = stride == 1 && inplanes == channels;
                x = self.bottleneck(x, idx, stride, connect)?;
                inplanes = channels;
                idx += 1;
            }
        }

        let x = self.conv_block(x, "conv2", 1, 0, false)?;
        // Global depthwise conv (kernel = feature-map size) + 1x1 linear.
        let x = self.conv_block(x, "linear7", 1, 0, true)?;
        let x = self.conv_block(x, "linear1", 1, 0, true)?;
        let [n, c, h, w] = x.dims();
        Ok(x.reshape([n, c * h * w]))
    }
}

// ---------------------------------------------------------------------------
// Inverted-residual (MobileNetV2-style) MobileFaceNet (foamliu)
// ---------------------------------------------------------------------------

/// Variant parameters of the inverted-residual MobileFaceNet.
#[derive(Debug, Clone)]
pub struct MfnV2Config {
    /// `[expansion, channels, num_blocks, first_stride]` rows
    /// (`inverted_residual_setting`).
    pub inverted_residual_setting: Vec<[usize; 4]>,
}

impl MfnV2Config {
    /// foamliu's `MobileFaceNet()` defaults (112x112 input, GDConv 7x7,
    /// 128-d). The rows are identical to Xiaoccer's bottleneck setting; the
    /// nets differ in activation (ReLU6 vs PReLU), state-dict layout and head.
    pub fn foamliu() -> Self {
        Self {
            inverted_residual_setting: vec![
                [2, 64, 5, 2],
                [4, 128, 1, 2],
                [2, 128, 6, 1],
                [4, 128, 1, 2],
                [2, 128, 2, 1],
            ],
        }
    }

    /// Builds the config from a manifest `arch` block.
    pub fn from_arch(arch: &MfnV2Arch) -> Self {
        Self {
            inverted_residual_setting: arch.inverted_residual_setting.clone(),
        }
    }
}

/// Inverted-residual MobileFaceNet embedder (foamliu `mobilefacenet.py
/// MobileFaceNet`, Apache-2.0 — the redistributable default embedder).
pub struct MobileFaceNetV2Embedder<B: Backend> {
    weights: Weights<B>,
    config: MfnV2Config,
}

impl<B: Backend> MobileFaceNetV2Embedder<B> {
    /// Wraps a loaded weight store with the variant config.
    pub fn new(weights: Weights<B>, config: MfnV2Config) -> Self {
        Self { weights, config }
    }

    /// `ConvBNReLU`: conv (no bias) + BN + ReLU6, keys `{prefix}.0.weight` /
    /// `{prefix}.1.*` (`nn.Sequential` layout). Kernel size and (depthwise)
    /// groups come from the weight shape.
    fn conv_bn_relu6(
        &self,
        x: Tensor<B, 4>,
        prefix: &str,
        stride: usize,
        padding: usize,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let w = &self.weights;
        let x = conv2d(
            x,
            w,
            &format!("{prefix}.0.weight"),
            None,
            [stride, stride],
            [padding, padding],
        )?;
        let x = batch_norm2d(x, w, &format!("{prefix}.1"), TORCH_BN_EPS)?;
        Ok(relu6(x))
    }

    /// `InvertedResidual` block `idx` (expansion != 1, the only layout the
    /// shipped setting uses): 1x1 expand ConvBNReLU6, depthwise 3x3 (stride
    /// s) ConvBNReLU6, 1x1 project + BN; identity shortcut when
    /// `stride == 1 && inp == oup`. Keys follow `features.{i}.conv.{0..3}`.
    fn inverted_residual(
        &self,
        x: Tensor<B, 4>,
        idx: usize,
        stride: usize,
        connect: bool,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let w = &self.weights;
        let p = format!("features.{idx}.conv");
        let short_cut = connect.then(|| x.clone());
        let y = self.conv_bn_relu6(x, &format!("{p}.0"), 1, 0)?;
        let y = self.conv_bn_relu6(y, &format!("{p}.1"), stride, 1)?;
        let y = conv2d(y, w, &format!("{p}.2.weight"), None, [1, 1], [0, 0])?;
        let y = batch_norm2d(y, w, &format!("{p}.3"), TORCH_BN_EPS)?;
        Ok(match short_cut {
            Some(s) => s + y,
            None => y,
        })
    }

    /// Runs the network on a normalized `[N, 3, 112, 112]` RGB crop
    /// (torchvision `ToTensor` + ImageNet `Normalize`, see the model
    /// manifest). Returns the raw (not L2-normalized) `[N, 128]` embedding.
    pub fn forward(&self, x: Tensor<B, 4>) -> Result<Tensor<B, 2>, WeightsError> {
        let w = &self.weights;

        // Stem: 3x3/2 ConvBNReLU6, then `DepthwiseSeparableConv` — depthwise
        // 3x3 + BN + ReLU, pointwise 1x1 + BN + ReLU (plain ReLU, not ReLU6).
        let x = self.conv_bn_relu6(x, "conv1", 2, 1)?;
        let x = conv2d(x, w, "dw_conv.depthwise.weight", None, [1, 1], [1, 1])?;
        let x = relu(batch_norm2d(x, w, "dw_conv.bn1", TORCH_BN_EPS)?);
        let x = conv2d(x, w, "dw_conv.pointwise.weight", None, [1, 1], [0, 0])?;
        let mut x = relu(batch_norm2d(x, w, "dw_conv.bn2", TORCH_BN_EPS)?);

        // Expand the setting rows into the flat `features` block sequence.
        let mut inplanes = 64usize;
        let mut idx = 0usize;
        for &[_expansion, channels, num_blocks, first_stride] in
            &self.config.inverted_residual_setting
        {
            for i in 0..num_blocks {
                let stride = if i == 0 { first_stride } else { 1 };
                let connect = stride == 1 && inplanes == channels;
                x = self.inverted_residual(x, idx, stride, connect)?;
                inplanes = channels;
                idx += 1;
            }
        }

        // Head: 1x1 ConvBNReLU6 to 512, global depthwise conv (`GDConv`,
        // kernel = feature-map size) + BN, biased 1x1 conv to the embedding
        // width + BN. No activation after the head (linear embedding).
        let x = self.conv_bn_relu6(x, "conv2", 1, 0)?;
        let x = conv2d(x, w, "gdconv.depthwise.weight", None, [1, 1], [0, 0])?;
        let x = batch_norm2d(x, w, "gdconv.bn", TORCH_BN_EPS)?;
        let x = conv2d_biased(x, w, "conv3", [1, 1], [0, 0])?;
        let x = batch_norm2d(x, w, "bn", TORCH_BN_EPS)?;
        let [n, c, h, wd] = x.dims();
        Ok(x.reshape([n, c * h * wd]))
    }
}

// ---------------------------------------------------------------------------
// IRN-50
// ---------------------------------------------------------------------------

/// Upstream IRN-50 BatchNorm epsilon (`irn50_pytorch.py`).
pub const IRN50_BN_EPS: f64 = 9.999_999_747_378_752e-6;

/// IRN-50 embedder (`face_feature/irn50_pytorch.py irn50_pytorch`).
///
/// All convs are bias-free with padding built out of explicit asymmetric
/// `F.pad` calls in the original; those pads are reproduced verbatim with
/// `Tensor::pad`. The head is `avg_pool(4x4)` → `Linear(16384, 512)` → BN1d →
/// maxout over the two 256-wide halves.
pub struct Irn50<B: Backend> {
    weights: Weights<B>,
}

impl<B: Backend> Irn50<B> {
    /// Wraps a loaded weight store (canonical `Convolution1` / `conv2_res1_*`
    /// / `fc1_1` / `bn_fc1` keys).
    pub fn new(weights: Weights<B>) -> Self {
        Self { weights }
    }

    fn conv(
        &self,
        x: Tensor<B, 4>,
        name: &str,
        stride: usize,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        conv2d(
            x,
            &self.weights,
            &format!("{name}.weight"),
            None,
            [stride, stride],
            [0, 0],
        )
    }

    fn bn(&self, x: Tensor<B, 4>, name: &str) -> Result<Tensor<B, 4>, WeightsError> {
        batch_norm2d(x, &self.weights, name, IRN50_BN_EPS)
    }

    /// conv (with the original's explicit symmetric-1 `F.pad` when `pad`) +
    /// BN + ReLU.
    fn conv_bn_relu(
        &self,
        x: Tensor<B, 4>,
        conv: &str,
        bn: &str,
        stride: usize,
        pad: bool,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let x = if pad { x.pad((1, 1, 1, 1), 0.0) } else { x };
        let x = self.conv(x, conv, stride)?;
        Ok(relu(self.bn(x, bn)?))
    }

    /// The standard three-conv residual branch of block `name`
    /// (`{name}_conv1` 1x1 → `{name}_conv2` padded 3x3 → `{name}_conv3` 1x1),
    /// with `conv1_stride` 2 only in `conv3_res1`.
    fn branch(
        &self,
        x: Tensor<B, 4>,
        name: &str,
        conv1_stride: usize,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let x = self.conv_bn_relu(
            x,
            &format!("{name}_conv1"),
            &format!("{name}_conv1_bn"),
            conv1_stride,
            false,
        )?;
        let x = self.conv_bn_relu(
            x,
            &format!("{name}_conv2"),
            &format!("{name}_conv2_bn"),
            1,
            true,
        )?;
        self.conv(x, &format!("{name}_conv3"), 1)
    }

    /// Identity residual block: pre-BN + ReLU, then branch, added to the
    /// block input (`convN_resM` for M >= 2 without a projection).
    fn identity_block(&self, x: Tensor<B, 4>, name: &str) -> Result<Tensor<B, 4>, WeightsError> {
        let pre = relu(self.bn(x.clone(), &format!("{name}_pre_bn"))?);
        Ok(x + self.branch(pre, name, 1)?)
    }

    /// Runs the network on a normalized `[N, 3, 128, 128]` input
    /// (`pixel / 256`, the upstream quirk). Returns the raw (not
    /// L2-normalized) `[N, 256]` maxout embedding.
    pub fn forward(&self, x: Tensor<B, 4>) -> Result<Tensor<B, 2>, WeightsError> {
        let w = &self.weights;

        // Stem: three 3x3 convs (first strided, third with explicit pad), a
        // -inf-padded 3x3/2 max pool, then 1x1 + 3x3 + padded strided 3x3.
        let x = self.conv_bn_relu(x, "Convolution1", "BatchNorm1", 2, false)?;
        let x = self.conv_bn_relu(x, "Convolution2", "BatchNorm2", 1, false)?;
        let x = self.conv_bn_relu(x, "Convolution3", "BatchNorm3", 1, true)?;
        // Pooling1: F.pad(x, (0, 1, 0, 1), -inf) then max_pool2d(3, stride 2).
        let x = x.pad((0, 1, 0, 1), f32::NEG_INFINITY);
        let x = max_pool2d(x, [3, 3], [2, 2], [0, 0], [1, 1]);
        let x = self.conv_bn_relu(x, "Convolution4", "BatchNorm4", 1, false)?;
        let x = self.conv_bn_relu(x, "Convolution5", "BatchNorm5", 1, false)?;
        let x = self.conv_bn_relu(x, "Convolution6", "BatchNorm6", 2, true)?;

        // conv2_res1: projection block without a pre-BN (input is post-ReLU).
        let x = self.conv(x.clone(), "conv2_res1_proj", 1)? + self.branch(x, "conv2_res1", 1)?;
        let x = self.identity_block(x, "conv2_res2")?;
        let x = self.identity_block(x, "conv2_res3")?;

        // conv3_res1: pre-BN, then strided projection and strided conv1.
        let pre = relu(self.bn(x, "conv3_res1_pre_bn")?);
        let x =
            self.conv(pre.clone(), "conv3_res1_proj", 2)? + self.branch(pre, "conv3_res1", 2)?;
        let x = self.identity_block(x, "conv3_res2")?;
        let x = self.identity_block(x, "conv3_res3")?;
        let x = self.identity_block(x, "conv3_res4")?;

        // conv4_res1: two-conv branch (padded 3x3 reduce + 1x1 expand).
        let pre = relu(self.bn(x, "conv4_res1_pre_bn")?);
        let proj = self.conv(pre.clone(), "conv4_res1_proj", 1)?;
        let y = self.conv_bn_relu(pre, "conv4_res1_conv1", "conv4_res1_conv1_bn", 1, true)?;
        let x = proj + self.conv(y, "conv4_res1_conv2", 1)?;

        // conv4_res2: projection block (1024 channels out) with pre-BN.
        let pre = relu(self.bn(x, "conv4_res2_pre_bn")?);
        let x = self.conv(pre.clone(), "conv4_res2_conv1_proj", 1)?
            + self.branch(pre, "conv4_res2", 1)?;
        let x = self.identity_block(x, "conv4_res3")?;

        // Head: BN + ReLU, 4x4 average pool, dense 512, BN1d, maxout halves.
        let x = relu(self.bn(x, "conv5_bn")?);
        let x = avg_pool2d(x, [4, 4], [1, 1], [0, 0], false);
        let [n, c, h, wd] = x.dims();
        let x = x.reshape([n, c * h * wd]);
        let x = linear_pt(x, w, "fc1_1.weight", None)?;
        let x = batch_norm1d(x, w, "bn_fc1", IRN50_BN_EPS)?;
        let half = x.dims()[1] / 2;
        let lo = x.clone().slice([0..n, 0..half]);
        let hi = x.slice([0..n, half..half * 2]);
        Ok(lo.max_pair(hi))
    }
}

//! Shared functional building blocks for the three networks.
//!
//! The models are implemented with Burn's functional tensor ops instead of
//! `burn::nn` modules + the Record system: weights stay in the [`Weights`]
//! store under their original PyTorch `state_dict` keys, and every forward
//! pass is explicit calls into `burn::tensor::module` plus the hand-written
//! batch-norm below. This keeps the state-dict keys the single naming source
//! of truth and works identically on the NdArray and Wgpu backends.

use burn::tensor::backend::Backend;
use burn::tensor::module as tm;
use burn::tensor::ops::ConvOptions;
use burn::tensor::{activation, Tensor};

use crate::weights::{Weights, WeightsError};

/// PyTorch's default BatchNorm epsilon (used by every net except IRN-50).
pub(crate) const TORCH_BN_EPS: f64 = 1e-5;

/// 2-d convolution with the kernel taken from the store at `weight_key`.
///
/// Groups are derived from the shapes exactly like PyTorch stores them:
/// `groups = C_in / weight.shape[1]` (1 for dense convs, `C` for depthwise).
pub(crate) fn conv2d<B: Backend>(
    x: Tensor<B, 4>,
    w: &Weights<B>,
    weight_key: &str,
    bias: Option<Tensor<B, 1>>,
    stride: [usize; 2],
    padding: [usize; 2],
) -> Result<Tensor<B, 4>, WeightsError> {
    let weight = w.t4(weight_key)?;
    let groups = x.dims()[1] / weight.dims()[1];
    Ok(tm::conv2d(
        x,
        weight,
        bias,
        ConvOptions::new(stride, padding, [1, 1], groups),
    ))
}

/// Convolution with a bias tensor stored next to the weight
/// (`<prefix>.weight` / `<prefix>.bias`).
pub(crate) fn conv2d_biased<B: Backend>(
    x: Tensor<B, 4>,
    w: &Weights<B>,
    prefix: &str,
    stride: [usize; 2],
    padding: [usize; 2],
) -> Result<Tensor<B, 4>, WeightsError> {
    let bias = w.t1(&format!("{prefix}.bias"))?;
    conv2d(
        x,
        w,
        &format!("{prefix}.weight"),
        Some(bias),
        stride,
        padding,
    )
}

/// Inference-mode 2-d batch norm:
/// `(x - running_mean) / sqrt(running_var + eps) * weight + bias`,
/// with parameters at `<prefix>.{weight,bias,running_mean,running_var}`.
pub(crate) fn batch_norm2d<B: Backend>(
    x: Tensor<B, 4>,
    w: &Weights<B>,
    prefix: &str,
    eps: f64,
) -> Result<Tensor<B, 4>, WeightsError> {
    let c = x.dims()[1];
    let shape = [1, c, 1, 1];
    let gamma = w.t1(&format!("{prefix}.weight"))?.reshape(shape);
    let beta = w.t1(&format!("{prefix}.bias"))?.reshape(shape);
    let mean = w.t1(&format!("{prefix}.running_mean"))?.reshape(shape);
    let var = w.t1(&format!("{prefix}.running_var"))?.reshape(shape);
    Ok((x - mean) / (var.add_scalar(eps).sqrt()) * gamma + beta)
}

/// Inference-mode 1-d batch norm over `[N, C]` activations.
pub(crate) fn batch_norm1d<B: Backend>(
    x: Tensor<B, 2>,
    w: &Weights<B>,
    prefix: &str,
    eps: f64,
) -> Result<Tensor<B, 2>, WeightsError> {
    let c = x.dims()[1];
    let shape = [1, c];
    let gamma = w.t1(&format!("{prefix}.weight"))?.reshape(shape);
    let beta = w.t1(&format!("{prefix}.bias"))?.reshape(shape);
    let mean = w.t1(&format!("{prefix}.running_mean"))?.reshape(shape);
    let var = w.t1(&format!("{prefix}.running_var"))?.reshape(shape);
    Ok((x - mean) / (var.add_scalar(eps).sqrt()) * gamma + beta)
}

/// `nn.ReLU6`: `min(max(x, 0), 6)`.
pub(crate) fn relu6<B: Backend, const D: usize>(x: Tensor<B, D>) -> Tensor<B, D> {
    x.clamp(0.0, 6.0)
}

/// PReLU with the per-channel slope tensor at `weight_key` (broadcast over
/// dim 1, matching `nn.PReLU(num_channels)`).
pub(crate) fn prelu<B: Backend, const D: usize>(
    x: Tensor<B, D>,
    w: &Weights<B>,
    weight_key: &str,
) -> Result<Tensor<B, D>, WeightsError> {
    let alpha = w.t1(weight_key)?;
    Ok(activation::prelu(x, alpha))
}

/// Linear layer with a PyTorch-layout weight (`[out, in]`) at `weight_key`:
/// `y = x @ W^T + b`.
pub(crate) fn linear_pt<B: Backend>(
    x: Tensor<B, 2>,
    w: &Weights<B>,
    weight_key: &str,
    bias: Option<Tensor<B, 1>>,
) -> Result<Tensor<B, 2>, WeightsError> {
    let weight = w.t2(weight_key)?;
    let out = x.matmul(weight.transpose());
    Ok(match bias {
        Some(b) => out + b.unsqueeze::<2>(),
        None => out,
    })
}

//! UltraFace slim-320 SSD face detector (Burn port).
//!
//! Faithful port of upstream `face_detect/vision/nn/mb_tiny.py` +
//! `face_detect/vision/ssd/{mb_tiny_fd.py,ssd.py}` with `is_test=True`:
//! the Mb_Tiny base (13 `conv_bn`/`conv_dw` blocks, `base_channel` 16), four
//! detection heads tapping the base net after layers 8, 11 and 13 plus one
//! extras block, softmaxed class confidences and locations decoded to
//! corner-form boxes through `rvface_core::boxes` (center variance 0.1, size
//! variance 0.2, priors for a 320x240 input).

use burn::tensor::activation::{relu, softmax};
use burn::tensor::backend::Backend;
use burn::tensor::Tensor;
use rvface_core::boxes::{
    center_to_corner, decode_locations, generate_priors, CenterBox, CENTER_VARIANCE, SIZE_VARIANCE,
};
use rvface_core::BBox;

use crate::ops::{batch_norm2d, conv2d, conv2d_biased, TORCH_BN_EPS};
use crate::weights::{Weights, WeightsError};

/// Strides of the 13 Mb_Tiny base blocks (`mb_tiny.py` `self.model`).
const BASE_STRIDES: [usize; 13] = [2, 1, 2, 1, 2, 1, 1, 1, 2, 1, 1, 2, 1];

/// Base-net indexes after which the first three heads tap
/// (`mb_tiny_fd.py` `source_layer_indexes`).
const SOURCE_LAYER_INDEXES: [usize; 3] = [8, 11, 13];

/// Raw `is_test=True` detector output for one image, before thresholding and
/// NMS: softmaxed `[background, face]` rows and the matching corner-form
/// boxes in normalized image units. Feed into `rvface_core::boxes::postprocess`.
#[derive(Debug, Clone)]
pub struct DetectorOutput {
    /// Softmaxed class probabilities per prior.
    pub confidences: Vec<[f32; 2]>,
    /// Decoded corner-form boxes (relative coordinates) per prior.
    pub boxes: Vec<BBox>,
}

/// The slim-320 SSD detector; construct once, call [`Self::forward`] per frame.
pub struct SsdSlim320<B: Backend> {
    weights: Weights<B>,
    priors: Vec<CenterBox>,
}

impl<B: Backend> SsdSlim320<B> {
    /// Number of classes ({background, face}).
    pub const NUM_CLASSES: usize = 2;
    /// Input size `[width, height]` the priors are generated for.
    pub const IMAGE_SIZE: [usize; 2] = [320, 240];

    /// Wraps a loaded weight store (canonical `base_net.*` / `extras.*` /
    /// `*_headers.*` keys) and precomputes the 4420 priors.
    pub fn new(weights: Weights<B>) -> Self {
        Self {
            weights,
            priors: generate_priors(Self::IMAGE_SIZE),
        }
    }

    /// `conv_bn`: 3x3 conv (stride s, pad 1, no bias) + BN + ReLU.
    fn conv_bn(
        &self,
        x: Tensor<B, 4>,
        idx: usize,
        stride: usize,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let w = &self.weights;
        let x = conv2d(
            x,
            w,
            &format!("base_net.{idx}.0.weight"),
            None,
            [stride, stride],
            [1, 1],
        )?;
        let x = batch_norm2d(x, w, &format!("base_net.{idx}.1"), TORCH_BN_EPS)?;
        Ok(relu(x))
    }

    /// `conv_dw`: depthwise 3x3 + BN + ReLU, then pointwise 1x1 + BN + ReLU.
    fn conv_dw(
        &self,
        x: Tensor<B, 4>,
        idx: usize,
        stride: usize,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let w = &self.weights;
        let x = conv2d(
            x,
            w,
            &format!("base_net.{idx}.0.weight"),
            None,
            [stride, stride],
            [1, 1],
        )?;
        let x = batch_norm2d(x, w, &format!("base_net.{idx}.1"), TORCH_BN_EPS)?;
        let x = relu(x);
        let x = conv2d(
            x,
            w,
            &format!("base_net.{idx}.3.weight"),
            None,
            [1, 1],
            [0, 0],
        )?;
        let x = batch_norm2d(x, w, &format!("base_net.{idx}.4"), TORCH_BN_EPS)?;
        Ok(relu(x))
    }

    fn base_layer(&self, x: Tensor<B, 4>, idx: usize) -> Result<Tensor<B, 4>, WeightsError> {
        if idx == 0 {
            self.conv_bn(x, 0, BASE_STRIDES[0])
        } else {
            self.conv_dw(x, idx, BASE_STRIDES[idx])
        }
    }

    /// `SeperableConv2d`: depthwise kxk (biased) + ReLU + pointwise 1x1 (biased).
    fn seperable_conv(
        &self,
        x: Tensor<B, 4>,
        prefix: &str,
        stride: usize,
        padding: usize,
    ) -> Result<Tensor<B, 4>, WeightsError> {
        let x = conv2d_biased(
            x,
            &self.weights,
            &format!("{prefix}.0"),
            [stride, stride],
            [padding, padding],
        )?;
        let x = relu(x);
        conv2d_biased(x, &self.weights, &format!("{prefix}.2"), [1, 1], [0, 0])
    }

    /// One detection head: heads 0-2 are `SeperableConv2d(k3, p1)`, head 3 a
    /// plain 3x3 conv. Returns `(confidence, location)` in
    /// `[N, H*W*anchors, {num_classes,4}]` layout (`SSD.compute_header`).
    fn compute_header(
        &self,
        idx: usize,
        x: &Tensor<B, 4>,
    ) -> Result<(Tensor<B, 3>, Tensor<B, 3>), WeightsError> {
        let mut out = Vec::with_capacity(2);
        for (kind, last) in [
            ("classification_headers", Self::NUM_CLASSES),
            ("regression_headers", 4),
        ] {
            let y = if idx < 3 {
                self.seperable_conv(x.clone(), &format!("{kind}.{idx}"), 1, 1)?
            } else {
                conv2d_biased(
                    x.clone(),
                    &self.weights,
                    &format!("{kind}.{idx}"),
                    [1, 1],
                    [1, 1],
                )?
            };
            let [n, _, _, _] = y.dims();
            let y = y.permute([0, 2, 3, 1]);
            let numel = y.dims().iter().product::<usize>();
            out.push(y.reshape([n, numel / (n * last), last]));
        }
        let location = out.pop().expect("regression output");
        let confidence = out.pop().expect("classification output");
        Ok((confidence, location))
    }

    /// Runs the `is_test=True` graph on a normalized `[1, 3, 240, 320]`
    /// input (`(pixel - 127) / 128`, RGB, NCHW).
    pub fn forward(&self, x: Tensor<B, 4>) -> Result<DetectorOutput, WeightsError> {
        let (confidences, locations) = self.forward_raw(x)?;
        let conf: Vec<f32> = confidences
            .into_data()
            .to_vec()
            .expect("confidences to host");
        let locs: Vec<f32> = locations.into_data().to_vec().expect("locations to host");
        Ok(self.decode_output(&conf, &locs))
    }

    /// Async variant of [`Self::forward`] for backends whose device-to-host
    /// reads cannot complete synchronously (Burn's wgpu backend on wasm:
    /// WebGPU buffer maps resolve via the browser event loop). Numerically
    /// identical to [`Self::forward`].
    pub async fn forward_async(&self, x: Tensor<B, 4>) -> Result<DetectorOutput, WeightsError> {
        let (confidences, locations) = self.forward_raw(x)?;
        let conf: Vec<f32> = confidences
            .into_data_async()
            .await
            .to_vec()
            .expect("confidences to host");
        let locs: Vec<f32> = locations
            .into_data_async()
            .await
            .to_vec()
            .expect("locations to host");
        Ok(self.decode_output(&conf, &locs))
    }

    /// Device-side portion of the forward pass: everything up to and
    /// including the class softmax; `(confidences, locations)` stay on the
    /// device so callers pick a sync or async host read.
    fn forward_raw(&self, x: Tensor<B, 4>) -> Result<(Tensor<B, 3>, Tensor<B, 3>), WeightsError> {
        assert_eq!(x.dims()[0], 1, "detector forward expects batch size 1");

        let mut confidences: Vec<Tensor<B, 3>> = Vec::with_capacity(4);
        let mut locations: Vec<Tensor<B, 3>> = Vec::with_capacity(4);

        let mut x = x;
        let mut start = 0usize;
        let mut header = 0usize;
        for end in SOURCE_LAYER_INDEXES {
            for idx in start..end {
                x = self.base_layer(x, idx)?;
            }
            start = end;
            let (confidence, location) = self.compute_header(header, &x)?;
            header += 1;
            confidences.push(confidence);
            locations.push(location);
        }

        // extras[0]: 1x1 conv + ReLU + SeperableConv2d(k3, s2, p1) + ReLU.
        x = conv2d_biased(x, &self.weights, "extras.0.0", [1, 1], [0, 0])?;
        x = relu(x);
        x = self.seperable_conv(x, "extras.0.2", 2, 1)?;
        x = relu(x);
        let (confidence, location) = self.compute_header(header, &x)?;
        confidences.push(confidence);
        locations.push(location);

        let confidences = Tensor::cat(confidences, 1);
        let locations = Tensor::cat(locations, 1);

        // is_test=True path: softmax over classes.
        let confidences = softmax(confidences, 2);
        Ok((confidences, locations))
    }

    /// Host-side tail of the forward pass: reshape the flat confidence /
    /// location reads and decode locations to corner-form boxes.
    fn decode_output(&self, conf: &[f32], locs: &[f32]) -> DetectorOutput {
        let confidences: Vec<[f32; 2]> = conf.chunks_exact(2).map(|c| [c[0], c[1]]).collect();
        let raw_locations: Vec<[f32; 4]> = locs
            .chunks_exact(4)
            .map(|c| [c[0], c[1], c[2], c[3]])
            .collect();
        let boxes = decode_locations(&raw_locations, &self.priors, CENTER_VARIANCE, SIZE_VARIANCE)
            .into_iter()
            .map(center_to_corner)
            .collect();

        DetectorOutput { confidences, boxes }
    }
}

//! Safetensors weight store and model-manifest schema.
//!
//! Weights keep the original PyTorch `state_dict` keys verbatim (see
//! `tools/naming.md`); the store is the single name-mapping point for the
//! functional forward passes in [`crate::detector`], [`crate::landmark`] and
//! [`crate::embedder`]. Non-float tensors (`num_batches_tracked` BatchNorm
//! buffers) are ignored on load.

use std::collections::{BTreeMap, HashMap};

use burn::tensor::backend::Backend;
use burn::tensor::{Tensor, TensorData};

/// Errors raised while loading weights or resolving tensors by name.
#[derive(Debug, thiserror::Error)]
pub enum WeightsError {
    /// The safetensors buffer failed to parse.
    #[error("invalid safetensors buffer: {0}")]
    InvalidSafetensors(String),
    /// A tensor required by a forward pass is absent from the store.
    #[error("missing tensor key: {0}")]
    MissingKey(String),
    /// A pipeline stage was invoked without its network loaded (a partial,
    /// detector-only pipeline — see `FacePipeline::detector_only`).
    #[error("pipeline stage `{0}` unavailable: its weights were not loaded")]
    MissingStage(&'static str),
    /// A tensor exists but its shape does not match what the caller expects.
    #[error("tensor `{key}`: expected rank {expected_rank}, got shape {actual:?}")]
    ShapeMismatch {
        /// State-dict key of the offending tensor.
        key: String,
        /// Rank the caller asked for.
        expected_rank: usize,
        /// Shape actually stored.
        actual: Vec<usize>,
    },
}

struct Entry<B: Backend> {
    /// Flattened f32 payload, already on the target device.
    flat: Tensor<B, 1>,
    shape: Vec<usize>,
}

/// A name → f32 tensor map loaded from a safetensors buffer.
///
/// Tensors are stored flattened on the device and reshaped on access, which
/// keeps the store rank-agnostic (state dicts mix 1-d BN vectors, 2-d linear
/// weights and 4-d conv kernels).
pub struct Weights<B: Backend> {
    tensors: HashMap<String, Entry<B>>,
}

impl<B: Backend> Weights<B> {
    /// Parses a safetensors buffer, uploading every f32 tensor to `device`.
    ///
    /// Integer tensors (`num_batches_tracked`) are skipped; safetensors
    /// payloads are little-endian by specification.
    pub fn from_safetensors(bytes: &[u8], device: &B::Device) -> Result<Self, WeightsError> {
        let parsed = safetensors::SafeTensors::deserialize(bytes)
            .map_err(|e| WeightsError::InvalidSafetensors(e.to_string()))?;
        let mut tensors = HashMap::new();
        for (name, view) in parsed.tensors() {
            if view.dtype() != safetensors::Dtype::F32 {
                continue;
            }
            // Flush near-zero weights to exact zero. Trained checkpoints can
            // carry huge numbers of denormal floats (the cunjian landmark
            // checkpoint has them in 75% of its weights), and denormal
            // arithmetic runs ~100x slower on x86 and in wasm, where FTZ
            // cannot be enabled. A 1e-30 weight contributes at most ~1e-27
            // to any activation — 23 orders of magnitude below the fp32
            // parity tolerance — so flushing is numerically free.
            const FLUSH_THRESHOLD: f32 = 1e-30;
            let values: Vec<f32> = view
                .data()
                .chunks_exact(4)
                .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
                .map(|v| if v.abs() < FLUSH_THRESHOLD { 0.0 } else { v })
                .collect();
            let shape = view.shape().to_vec();
            let len = values.len();
            let flat = Tensor::from_data(TensorData::new(values, [len]), device);
            tensors.insert(name, Entry { flat, shape });
        }
        Ok(Self { tensors })
    }

    /// Number of (float) tensors in the store.
    pub fn len(&self) -> usize {
        self.tensors.len()
    }

    /// True when the store holds no tensors.
    pub fn is_empty(&self) -> bool {
        self.tensors.is_empty()
    }

    /// Whether `key` is present in the store.
    pub fn contains(&self, key: &str) -> bool {
        self.tensors.contains_key(key)
    }

    fn entry(&self, key: &str) -> Result<&Entry<B>, WeightsError> {
        self.tensors
            .get(key)
            .ok_or_else(|| WeightsError::MissingKey(key.to_owned()))
    }

    fn rank_err(key: &str, expected_rank: usize, shape: &[usize]) -> WeightsError {
        WeightsError::ShapeMismatch {
            key: key.to_owned(),
            expected_rank,
            actual: shape.to_vec(),
        }
    }

    /// 1-d tensor (BN parameter, bias, PReLU slope) by state-dict key.
    pub fn t1(&self, key: &str) -> Result<Tensor<B, 1>, WeightsError> {
        let e = self.entry(key)?;
        if e.shape.len() != 1 {
            return Err(Self::rank_err(key, 1, &e.shape));
        }
        Ok(e.flat.clone())
    }

    /// 2-d tensor (linear weight, PyTorch `[out, in]` layout) by key.
    pub fn t2(&self, key: &str) -> Result<Tensor<B, 2>, WeightsError> {
        let e = self.entry(key)?;
        if e.shape.len() != 2 {
            return Err(Self::rank_err(key, 2, &e.shape));
        }
        Ok(e.flat.clone().reshape([e.shape[0], e.shape[1]]))
    }

    /// 4-d tensor (conv kernel, `[out, in/groups, kh, kw]`) by key.
    pub fn t4(&self, key: &str) -> Result<Tensor<B, 4>, WeightsError> {
        let e = self.entry(key)?;
        if e.shape.len() != 4 {
            return Err(Self::rank_err(key, 4, &e.shape));
        }
        Ok(e.flat
            .clone()
            .reshape([e.shape[0], e.shape[1], e.shape[2], e.shape[3]]))
    }
}

// ---------------------------------------------------------------------------
// Model manifest schema (models/<name>.manifest.json, tools/naming.md)
// ---------------------------------------------------------------------------

/// `models/<name>.manifest.json`: provenance, preprocessing contract, exact
/// architecture hyperparameters and the full tensor key/shape list.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct ModelManifest {
    /// File stem, e.g. `detector-slim320`.
    pub name: String,
    /// Sibling safetensors file name.
    pub file: String,
    /// Exact download URL of the original checkpoint (null for IRN-50).
    pub source_url: Option<String>,
    /// SHA-256 pin of the original `.pth`/`.ckpt`/`.npy`.
    pub source_sha256: Option<String>,
    /// Provenance and license notes (ADR-0003).
    pub license: String,
    /// Preprocessing contract for the network input.
    pub input: InputSpec,
    /// Human-readable output contract.
    pub output: String,
    /// Exact architecture hyperparameters, dispatched on `family`.
    pub arch: Arch,
    /// State-dict keys with shapes/dtypes (state-dict order in the file).
    pub tensors: BTreeMap<String, TensorSpec>,
}

/// The `input` block of a model manifest.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct InputSpec {
    /// Input width in pixels.
    pub width: usize,
    /// Input height in pixels.
    pub height: usize,
    /// Input channel count.
    pub channels: usize,
    /// Channel order the net was trained on (`rgb` | `bgr`).
    pub colorspace: String,
    /// Per-channel mean, subtracted first.
    pub mean: Vec<f32>,
    /// Multiplied after mean subtraction.
    pub scale: f64,
    /// Optional per-channel std divisor applied after mean/scale
    /// (torchvision `Normalize`): `out[c] = (pixel - mean[c]) * scale / std[c]`.
    #[serde(default)]
    pub std: Option<Vec<f32>>,
    /// Tensor layout (always `nchw`).
    pub layout: String,
    /// Stage-specific cropping/quirks.
    #[serde(default)]
    pub note: Option<String>,
}

/// One entry of the manifest `tensors` map.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct TensorSpec {
    /// Tensor shape (empty for 0-dim buffers).
    pub shape: Vec<usize>,
    /// Dtype string (`float32` | `int64`).
    pub dtype: String,
}

/// Architecture config, tagged by `family` (see `tools/naming.md`).
#[derive(Debug, Clone, serde::Deserialize)]
#[serde(tag = "family")]
pub enum Arch {
    /// Ultra-Light-Fast-Generic-Face-Detector SSD.
    #[serde(rename = "ultraface-ssd")]
    UltrafaceSsd(SsdArch),
    /// MobileFaceNet (both flavors, tagged by `style`).
    #[serde(rename = "mobilefacenet")]
    MobileFaceNet(MfnArch),
    /// Inception-ResNet-50 embedder.
    #[serde(rename = "irn50")]
    Irn50(Irn50Arch),
}

/// `family: "ultraface-ssd"` hyperparameters.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct SsdArch {
    /// Variant name (`slim320`).
    pub variant: String,
    /// Number of classes ({background, face} = 2).
    pub num_classes: usize,
    /// Total prior count (4420 for slim-320).
    pub num_priors: usize,
    /// Mb_Tiny base channel (16).
    pub base_channel: usize,
    /// Feature-map sizes, `[widths, heights]` per head.
    pub feature_maps: Vec<Vec<usize>>,
    /// Anchor side lengths (px) per feature map.
    pub min_boxes: Vec<Vec<f32>>,
    /// SSD decode center variance.
    pub center_variance: f32,
    /// SSD decode size variance.
    pub size_variance: f32,
    /// Base-net indexes after which detection heads tap.
    pub source_layer_indexes: Vec<usize>,
}

/// `family: "mobilefacenet"`, dispatched on `style`.
#[derive(Debug, Clone, serde::Deserialize)]
#[serde(tag = "style")]
pub enum MfnArch {
    /// insightface/cunjian flavor (`Conv_block`/`Depth_Wise`/`Residual`).
    #[serde(rename = "depthwise-residual")]
    DepthwiseResidual(MfnDwArch),
    /// paper/Xiaoccer flavor (inverted-bottleneck blocks).
    #[serde(rename = "bottleneck")]
    Bottleneck(MfnBottleneckArch),
    /// foamliu flavor (MobileNetV2-style inverted residuals, ReLU6).
    #[serde(rename = "inverted-residual-v2")]
    InvertedResidualV2(MfnV2Arch),
}

/// Non-linearity used by a MobileFaceNet variant.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Activation {
    /// `nn.ReLU`.
    Relu,
    /// `nn.ReLU6` (`min(max(x, 0), 6)`).
    Relu6,
    /// `nn.PReLU` with per-channel slopes.
    Prelu,
}

/// Depthwise-residual MobileFaceNet hyperparameters.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct MfnDwArch {
    /// Input channel count (1 gray / 3 color).
    pub in_channels: usize,
    /// Input spatial size `[height, width]`.
    pub input_size: [usize; 2],
    /// Block non-linearity.
    pub activation: Activation,
    /// Output channels per named stage.
    pub channels: MfnDwChannels,
    /// Hidden (expansion) widths of the `Depth_Wise` stages.
    pub groups: MfnDwGroups,
    /// `num_block` of each `Residual` stage.
    pub residual_num_blocks: MfnDwResidualBlocks,
    /// GDC depthwise kernel `[kh, kw]`.
    pub gdc_kernel: [usize; 2],
    /// Whether the GDC `Linear` has a bias.
    pub gdc_linear_bias: bool,
    /// GDC linear output width.
    pub embedding_size: usize,
    /// Network output dimension.
    pub output_dim: usize,
}

/// `channels` block of [`MfnDwArch`].
#[derive(Debug, Clone, serde::Deserialize)]
#[allow(missing_docs)]
pub struct MfnDwChannels {
    pub conv1: usize,
    pub conv2_dw: usize,
    pub conv_23: usize,
    pub conv_3: usize,
    pub conv_34: usize,
    pub conv_4: usize,
    pub conv_45: usize,
    pub conv_5: usize,
    pub conv_6_sep: usize,
}

/// `groups` block of [`MfnDwArch`] (hidden widths of the bottlenecks).
#[derive(Debug, Clone, serde::Deserialize)]
#[allow(missing_docs)]
pub struct MfnDwGroups {
    pub conv_23: usize,
    pub conv_3: usize,
    pub conv_34: usize,
    pub conv_4: usize,
    pub conv_45: usize,
    pub conv_5: usize,
}

/// `residual_num_blocks` block of [`MfnDwArch`].
#[derive(Debug, Clone, serde::Deserialize)]
#[allow(missing_docs)]
pub struct MfnDwResidualBlocks {
    pub conv_3: usize,
    pub conv_4: usize,
    pub conv_5: usize,
}

/// Bottleneck-style MobileFaceNet hyperparameters (Xiaoccer flavor).
#[derive(Debug, Clone, serde::Deserialize)]
pub struct MfnBottleneckArch {
    /// Input channel count.
    pub in_channels: usize,
    /// Input spatial size `[height, width]`.
    pub input_size: [usize; 2],
    /// Block non-linearity.
    pub activation: Activation,
    /// Stem convolution.
    pub conv1: ConvSpec,
    /// Depthwise convolution after the stem.
    pub dw_conv1: ConvSpec,
    /// `[expansion, channels, num_blocks, first_stride]` rows.
    pub bottleneck_setting: Vec<[usize; 4]>,
    /// Column names of `bottleneck_setting` (documentation only).
    #[serde(default)]
    pub bottleneck_setting_columns: Option<Vec<String>>,
    /// 1x1 expansion before the global depthwise conv.
    pub conv2: ConvSpec,
    /// GDC depthwise kernel `[kh, kw]`.
    pub gdc_kernel: [usize; 2],
    /// Whether the GDC linear stage has a bias.
    pub gdc_linear_bias: bool,
    /// Embedding width.
    pub embedding_size: usize,
    /// Network output dimension.
    pub output_dim: usize,
}

/// Inverted-residual (MobileNetV2-style) MobileFaceNet hyperparameters
/// (foamliu flavor: ReLU6 blocks — plain ReLU in the depthwise-separable
/// stem — GDConv head with a biased 1x1 embedding conv).
#[derive(Debug, Clone, serde::Deserialize)]
pub struct MfnV2Arch {
    /// Input channel count.
    pub in_channels: usize,
    /// Input spatial size `[height, width]`.
    pub input_size: [usize; 2],
    /// Block non-linearity.
    pub activation: Activation,
    /// `[expansion, channels, num_blocks, first_stride]` rows
    /// (`inverted_residual_setting`; expansion 1 is not supported — the
    /// shipped setting never uses it and its state-dict layout differs).
    pub inverted_residual_setting: Vec<[usize; 4]>,
    /// Column names of `inverted_residual_setting` (documentation only).
    #[serde(default)]
    pub inverted_residual_setting_columns: Option<Vec<String>>,
    /// GDC depthwise kernel `[kh, kw]`.
    pub gdc_kernel: [usize; 2],
    /// Embedding width.
    pub embedding_size: usize,
    /// Network output dimension.
    pub output_dim: usize,
}

/// A convolution hyperparameter row inside a manifest arch block.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct ConvSpec {
    /// Output channels.
    pub out: usize,
    /// Square kernel size.
    pub kernel: usize,
    /// Stride (defaults to 1).
    #[serde(default = "one")]
    pub stride: usize,
    /// Padding (defaults to 0).
    #[serde(default)]
    pub pad: usize,
}

fn one() -> usize {
    1
}

/// `family: "irn50"` hyperparameters.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct Irn50Arch {
    /// Input spatial size `[height, width]`.
    pub input_size: [usize; 2],
    /// BatchNorm epsilon (upstream 9.999999747378752e-06).
    pub bn_eps: f64,
    /// Width of the final dense layer before maxout.
    pub fc_dim: usize,
    /// Output dimension after maxout.
    pub output_dim: usize,
    /// Whether the maxout head is present (always true upstream).
    pub maxout: bool,
}

#[cfg(test)]
mod tests {
    use super::*;

    fn models_dir() -> std::path::PathBuf {
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../models")
    }

    fn load_manifest(name: &str) -> Option<ModelManifest> {
        let path = models_dir().join(format!("{name}.manifest.json"));
        let json = std::fs::read_to_string(&path).ok()?;
        Some(serde_json::from_str(&json).expect("manifest parses"))
    }

    #[test]
    fn detector_manifest_parses() {
        let Some(m) = load_manifest("detector-slim320") else {
            eprintln!("skipping: models/detector-slim320.manifest.json absent");
            return;
        };
        let Arch::UltrafaceSsd(arch) = &m.arch else {
            panic!("wrong family: {:?}", m.arch);
        };
        assert_eq!(arch.num_priors, 4420);
        assert_eq!(arch.base_channel, 16);
        assert_eq!(arch.source_layer_indexes, vec![8, 11, 13]);
        assert_eq!(m.tensors.len(), 184);
    }

    #[test]
    fn landmark_manifest_parses() {
        let Some(m) = load_manifest("landmark-mfn68") else {
            eprintln!("skipping: models/landmark-mfn68.manifest.json absent");
            return;
        };
        let Arch::MobileFaceNet(MfnArch::DepthwiseResidual(arch)) = &m.arch else {
            panic!("wrong family/style: {:?}", m.arch);
        };
        assert_eq!(arch.activation, Activation::Prelu);
        assert_eq!(arch.residual_num_blocks.conv_3, 4);
        assert_eq!(arch.residual_num_blocks.conv_4, 6);
        assert_eq!(arch.residual_num_blocks.conv_5, 2);
        assert_eq!(arch.gdc_kernel, [7, 7]);
        assert!(!arch.gdc_linear_bias);
        assert_eq!(arch.embedding_size, 136);
    }

    #[test]
    fn embedder_manifest_parses() {
        let Some(m) = load_manifest("embedder-mfn") else {
            eprintln!("skipping: models/embedder-mfn.manifest.json absent");
            return;
        };
        let Arch::MobileFaceNet(MfnArch::Bottleneck(arch)) = &m.arch else {
            panic!("wrong family/style: {:?}", m.arch);
        };
        assert_eq!(
            arch.bottleneck_setting,
            vec![
                [2, 64, 5, 2],
                [4, 128, 1, 2],
                [2, 128, 6, 1],
                [4, 128, 1, 2],
                [2, 128, 2, 1]
            ]
        );
        assert_eq!(arch.gdc_kernel, [7, 6]);
        assert_eq!(arch.embedding_size, 128);
        assert_eq!(arch.conv1.stride, 2);
        assert_eq!(arch.conv2.stride, 1);
    }

    #[test]
    fn embedder_foamliu_manifest_parses() {
        let Some(m) = load_manifest("embedder-foamliu") else {
            eprintln!("skipping: models/embedder-foamliu.manifest.json absent");
            return;
        };
        let Arch::MobileFaceNet(MfnArch::InvertedResidualV2(arch)) = &m.arch else {
            panic!("wrong family/style: {:?}", m.arch);
        };
        assert_eq!(arch.activation, Activation::Relu6);
        assert_eq!(
            arch.inverted_residual_setting,
            vec![
                [2, 64, 5, 2],
                [4, 128, 1, 2],
                [2, 128, 6, 1],
                [4, 128, 1, 2],
                [2, 128, 2, 1]
            ]
        );
        assert_eq!(arch.input_size, [112, 112]);
        assert_eq!(arch.gdc_kernel, [7, 7]);
        assert_eq!(arch.embedding_size, 128);
        // Apache-2.0 is what makes this embedder redistributable (ADR-0003
        // addendum); a manifest regenerated without the license note is a bug.
        assert!(m.license.contains("Apache"), "license: {}", m.license);
        // torchvision Normalize folded to pixel domain.
        assert_eq!(m.input.mean, vec![123.675, 116.28, 103.53]);
        assert_eq!(m.input.std.as_deref(), Some(&[0.229, 0.224, 0.225][..]));
        assert_eq!(m.tensors.len(), 307);
    }
}

//! The full rvFACE inference pipeline: upstream `run.py GetImageInfo`
//! assembled entirely in Rust.
//!
//! Flow per image (exact upstream order): detect faces (slim-320 SSD at
//! 320x240) -> truncate to `max_faces` (`boxes[:faceMaxCount]`) -> per face:
//! 68-point landmarks (cunjian MobileFaceNet on a 1.2x square crop) -> head
//! pose from the landmarks -> eyes-level 128x128 alignment -> embedding ->
//! L2 normalization. Comparison downstream uses
//! `rvface_core::similarity::similarity` (`(dot + 1) * 50`, threshold 75).
//!
//! Channel-order bookkeeping: upstream loads images with `cv2.imread` (BGR).
//! The detector converts to RGB before preprocessing; the landmark net and
//! the IRN-50 embedder consume BGR directly. [`FacePipeline::analyze`] takes
//! an **RGB8** [`Image`] and performs the equivalent swaps internally, so the
//! net effect is identical to the upstream BGR flow.
//!
//! Everything here works from in-memory buffers only (no `std::fs`), so the
//! module compiles unchanged for `wasm32-unknown-unknown`.

use burn::tensor::backend::Backend;
use burn::tensor::{Tensor, TensorData};

use rvface_core::align::{align_vertical, Landmarks};
use rvface_core::boxes::{postprocess, PostprocessParams};
use rvface_core::image::{
    resize_bilinear_f32, swap_rb, to_chw_f32, Image, DETECTOR_MEAN, DETECTOR_SCALE, EMBEDDER_SCALE,
    LANDMARK_SCALE,
};
use rvface_core::pose::estimate_pose;
use rvface_core::similarity::l2_normalize;
use rvface_core::{Detection, Pose};

use crate::detector::SsdSlim320;
use crate::embedder::{
    Irn50, MfnBottleneckConfig, MfnV2Config, MobileFaceNetEmbedder, MobileFaceNetV2Embedder,
};
use crate::landmark::{MfnDwConfig, MobileFaceNetDw};
use crate::weights::{Weights, WeightsError};

/// Landmark-net input side (cunjian `MobileFaceNet([112, 112], 136)`).
const LANDMARK_INPUT: usize = 112;
/// Crop enlargement factor of the landmark square (`int(min(w, h) * 1.2)`).
const LANDMARK_CROP_SCALE: f32 = 1.2;
/// MobileFaceNet embedder input `[width, height]` (Xiaoccer, 112x96 crop).
const MFN_INPUT: [usize; 2] = [96, 112];
/// MobileFaceNet embedder normalization mean (`(x - 127.5) / 128`).
const MFN_MEAN: [f32; 3] = [127.5, 127.5, 127.5];
/// MobileFaceNet embedder normalization scale.
const MFN_SCALE: f32 = 1.0 / 128.0;
/// foamliu MobileFaceNet embedder input side (112x112 RGB).
const MFN_V2_INPUT: usize = 112;
/// foamliu normalization: torchvision `ToTensor` + ImageNet `Normalize`,
/// folded to the pixel domain — mean `255 * {0.485, 0.456, 0.406}` …
const MFN_V2_MEAN: [f32; 3] = [123.675, 116.28, 103.53];
/// … and per-channel scale `1 / (255 * {0.229, 0.224, 0.225})`.
const MFN_V2_SCALE: [f32; 3] = [
    1.0 / (255.0 * 0.229),
    1.0 / (255.0 * 0.224),
    1.0 / (255.0 * 0.225),
];

/// One fully analyzed face.
#[derive(Debug, Clone, serde::Serialize)]
pub struct Face {
    /// Detector box (pixel coordinates in the source image) and score.
    pub detection: Detection,
    /// 68 landmarks, pixel coordinates in the source image.
    #[serde(serialize_with = "serialize_landmarks")]
    pub landmarks: Landmarks,
    /// Head pose estimated from the landmarks.
    pub pose: Pose,
    /// L2-normalized embedding (128-d MobileFaceNet / 256-d IRN-50).
    pub embedding: Vec<f32>,
}

/// Serde stops at 32-element arrays; serialize the 68 points as a sequence.
fn serialize_landmarks<S: serde::Serializer>(
    landmarks: &Landmarks,
    serializer: S,
) -> Result<S::Ok, S::Error> {
    serializer.collect_seq(landmarks.iter())
}

/// The embedding network of the pipeline.
///
/// - [`Embedder::Irn50`] is the **exact upstream path**
///   (`face_feature/GetFeature.py`): the aligned 128x128 crop is fed in the
///   source image's channel order — BGR upstream, since `cv2.imread` loads
///   BGR and `align_vertical` preserves channel order — scaled by 1/256
///   (upstream divides by 256, not 255), no mean subtraction. Use it when
///   converted `irn50_pytorch.npy` weights are available.
/// - [`Embedder::MobileFaceNet`] is a documented **adaptation**: the upstream
///   IRN-50 weights are unpublished, so a substitute embedder is the Xiaoccer
///   MobileFaceNet (112x96 RGB input, `(x - 127.5) / 128`). Its reference
///   pipeline crops SphereFace-style 112x96 MTCNN alignments; rvFACE instead
///   bilinear-resizes the pipeline's aligned 128x128 crop to 96x112. Scores
///   are therefore *not* bit-comparable with the upstream demo — the IRN-50
///   variant is the parity path.
/// - [`Embedder::MobileFaceNetV2`] is the **default** (and the only
///   redistributable) embedder: foamliu's Apache-2.0 inverted-residual
///   MobileFaceNet (112x112 RGB, torchvision ImageNet normalization). Like
///   the Xiaoccer variant it is an adaptation — its reference crops are
///   InsightFace-aligned 112x112, rvFACE resizes the aligned 128x128 crop.
pub enum Embedder<B: Backend> {
    /// Xiaoccer MobileFaceNet, 128-d (adaptation, see enum docs).
    MobileFaceNet(MobileFaceNetEmbedder<B>),
    /// foamliu inverted-residual MobileFaceNet, 128-d (default; Apache-2.0).
    MobileFaceNetV2(MobileFaceNetV2Embedder<B>),
    /// Upstream IRN-50, 256-d (exact upstream architecture and preprocessing).
    Irn50(Irn50<B>),
}

impl<B: Backend> Embedder<B> {
    /// Loads the MobileFaceNet embedder from a safetensors buffer.
    pub fn mobilefacenet_from_safetensors(
        bytes: &[u8],
        config: MfnBottleneckConfig,
        device: &B::Device,
    ) -> Result<Self, WeightsError> {
        let weights = Weights::from_safetensors(bytes, device)?;
        Ok(Self::MobileFaceNet(MobileFaceNetEmbedder::new(
            weights, config,
        )))
    }

    /// Loads the foamliu inverted-residual MobileFaceNet embedder from a
    /// safetensors buffer.
    pub fn mobilefacenet_v2_from_safetensors(
        bytes: &[u8],
        config: MfnV2Config,
        device: &B::Device,
    ) -> Result<Self, WeightsError> {
        let weights = Weights::from_safetensors(bytes, device)?;
        Ok(Self::MobileFaceNetV2(MobileFaceNetV2Embedder::new(
            weights, config,
        )))
    }

    /// Loads the IRN-50 embedder from a safetensors buffer.
    pub fn irn50_from_safetensors(bytes: &[u8], device: &B::Device) -> Result<Self, WeightsError> {
        let weights = Weights::from_safetensors(bytes, device)?;
        Ok(Self::Irn50(Irn50::new(weights)))
    }

    /// Embeds an aligned 128x128 **RGB** crop (as produced by
    /// `align_vertical` on an RGB source). Returns the raw, not yet
    /// L2-normalized embedding.
    fn embed(&self, aligned: Image, device: &B::Device) -> Result<Vec<f32>, WeightsError> {
        let raw = self.embed_raw(aligned, device)?;
        Ok(raw.into_data().to_vec().expect("embedding to host"))
    }

    /// Async-read variant of [`Self::embed`] (see [`FacePipeline::analyze_async`]).
    async fn embed_async(
        &self,
        aligned: Image,
        device: &B::Device,
    ) -> Result<Vec<f32>, WeightsError> {
        let raw = self.embed_raw(aligned, device)?;
        Ok(raw
            .into_data_async()
            .await
            .to_vec()
            .expect("embedding to host"))
    }

    /// Device-side embedding forward; the result stays on the device.
    fn embed_raw(
        &self,
        mut aligned: Image,
        device: &B::Device,
    ) -> Result<Tensor<B, 2>, WeightsError> {
        let raw = match self {
            // Adaptation (see enum docs): resize the aligned 128x128 RGB crop
            // to the net's 96x112 input, normalize (x - 127.5) / 128.
            Self::MobileFaceNet(net) => {
                let [w, h] = MFN_INPUT;
                let hwc = resize_bilinear_f32(&aligned, w, h);
                let chw = hwc_to_chw(&hwc, w, h, &MFN_MEAN, &[MFN_SCALE; 3]);
                let input = Tensor::from_data(TensorData::new(chw, [1, 3, h, w]), device);
                net.forward(input)?
            }
            // Adaptation (see enum docs): resize the aligned 128x128 RGB crop
            // to 112x112, torchvision ImageNet normalization (per-channel).
            Self::MobileFaceNetV2(net) => {
                let side = MFN_V2_INPUT;
                let hwc = resize_bilinear_f32(&aligned, side, side);
                let chw = hwc_to_chw(&hwc, side, side, &MFN_V2_MEAN, &MFN_V2_SCALE);
                let input = Tensor::from_data(TensorData::new(chw, [1, 3, side, side]), device);
                net.forward(input)?
            }
            // Exact upstream path: `GetFeature.py` feeds the aligned crop in
            // the cv2 (BGR) channel order, scaled by 1/256. Our source is
            // RGB, so swap to BGR before the CHW conversion.
            Self::Irn50(net) => {
                swap_rb(&mut aligned);
                let chw = to_chw_f32(&aligned, &[0.0; 3], EMBEDDER_SCALE);
                let (w, h) = (aligned.width, aligned.height);
                let input = Tensor::from_data(TensorData::new(chw, [1, 3, h, w]), device);
                net.forward(input)?
            }
        };
        Ok(raw)
    }
}

/// The assembled detector + landmark + pose + alignment + embedding pipeline.
///
/// The landmark and embedder stages are optional: a **detector-only**
/// pipeline ([`Self::detector_only`]) supports [`Self::detect`] but fails
/// [`Self::analyze`] with [`WeightsError::MissingStage`] — used by the web
/// demo when the non-redistributable landmark weights are absent.
pub struct FacePipeline<B: Backend> {
    detector: SsdSlim320<B>,
    landmark: Option<MobileFaceNetDw<B>>,
    embedder: Option<Embedder<B>>,
    device: B::Device,
}

impl<B: Backend> FacePipeline<B> {
    /// Assembles a full pipeline from already-constructed networks.
    pub fn new(
        detector: SsdSlim320<B>,
        landmark: MobileFaceNetDw<B>,
        embedder: Embedder<B>,
        device: B::Device,
    ) -> Self {
        Self {
            detector,
            landmark: Some(landmark),
            embedder: Some(embedder),
            device,
        }
    }

    /// Assembles a detector-only pipeline: [`Self::detect`] /
    /// [`Self::detect_async`] work, [`Self::analyze`] errors with
    /// [`WeightsError::MissingStage`].
    pub fn detector_only(detector: SsdSlim320<B>, device: B::Device) -> Self {
        Self {
            detector,
            landmark: None,
            embedder: None,
            device,
        }
    }

    /// [`Self::detector_only`] from a raw detector safetensors buffer.
    pub fn detector_only_from_safetensors(
        detector_bytes: &[u8],
        device: &B::Device,
    ) -> Result<Self, WeightsError> {
        let detector = SsdSlim320::new(Weights::from_safetensors(detector_bytes, device)?);
        Ok(Self::detector_only(detector, device.clone()))
    }

    /// Whether the landmark + embedder stages are loaded (i.e. whether
    /// [`Self::analyze`] can run the full flow).
    pub fn is_full(&self) -> bool {
        self.landmark.is_some() && self.embedder.is_some()
    }

    /// Builds the pipeline from raw safetensors buffers: the slim-320
    /// detector, the cunjian-112 landmark net (config usually
    /// [`MfnDwConfig::cunjian_112`] or [`MfnDwConfig::from_arch`] on the
    /// model manifest) and a pre-built [`Embedder`]. Wasm-friendly: bytes in,
    /// no filesystem access.
    pub fn from_safetensors(
        detector_bytes: &[u8],
        landmark_bytes: &[u8],
        landmark_config: MfnDwConfig,
        embedder: Embedder<B>,
        device: &B::Device,
    ) -> Result<Self, WeightsError> {
        let detector = SsdSlim320::new(Weights::from_safetensors(detector_bytes, device)?);
        let landmark = MobileFaceNetDw::new(
            Weights::from_safetensors(landmark_bytes, device)?,
            landmark_config,
        );
        Ok(Self::new(detector, landmark, embedder, device.clone()))
    }

    /// Runs the full upstream `GetImageInfo` flow on an **RGB8** image and
    /// returns at most `max_faces` analyzed faces, in detector pick order
    /// (score-descending).
    ///
    /// Errors only on missing/misshaped weight tensors; an image without
    /// detectable faces yields an empty vector.
    pub fn analyze(&self, image: &Image, max_faces: usize) -> Result<Vec<Face>, WeightsError> {
        assert_eq!(image.channels, 3, "analyze expects an RGB8 image");
        let embedder = self
            .embedder
            .as_ref()
            .ok_or(WeightsError::MissingStage("embedder"))?;
        let detections = self.detect(image, max_faces)?;
        let mut faces = Vec::with_capacity(detections.len());
        for detection in detections {
            // Degenerate boxes (sub-pixel landmark crops) cannot be analyzed;
            // upstream would crash here, we skip the face instead.
            let Some(landmarks) = self.landmarks(image, &detection)? else {
                continue;
            };
            let pose = estimate_pose(&landmarks);
            let aligned = align_vertical(image, &landmarks);
            let mut embedding = embedder.embed(aligned, &self.device)?;
            l2_normalize(&mut embedding);
            faces.push(Face {
                detection,
                landmarks,
                pose,
                embedding,
            });
        }
        Ok(faces)
    }

    /// Async variant of [`Self::analyze`] for backends whose device-to-host
    /// tensor reads cannot complete synchronously — Burn's wgpu backend on
    /// wasm, where WebGPU buffer mapping resolves via the browser event loop.
    /// Flow and numerics are identical to [`Self::analyze`].
    pub async fn analyze_async(
        &self,
        image: &Image,
        max_faces: usize,
    ) -> Result<Vec<Face>, WeightsError> {
        assert_eq!(image.channels, 3, "analyze expects an RGB8 image");
        let embedder = self
            .embedder
            .as_ref()
            .ok_or(WeightsError::MissingStage("embedder"))?;
        let detections = self.detect_async(image, max_faces).await?;
        let mut faces = Vec::with_capacity(detections.len());
        for detection in detections {
            let Some(landmarks) = self.landmarks_async(image, &detection).await? else {
                continue;
            };
            let pose = estimate_pose(&landmarks);
            let aligned = align_vertical(image, &landmarks);
            let mut embedding = embedder.embed_async(aligned, &self.device).await?;
            l2_normalize(&mut embedding);
            faces.push(Face {
                detection,
                landmarks,
                pose,
                embedding,
            });
        }
        Ok(faces)
    }

    /// Detection stage: resize to 320x240 (kept in f32 — see note), normalize
    /// `(x - 127) / 128`, forward, then the exact upstream postprocessing
    /// chain (`Predictor.predict` + `get_face_boundingbox`) truncated to
    /// `max_faces` (`boxes[:faceMaxCount]`).
    ///
    /// Note: upstream `cv2.resize`s the u8 image (fixed-point, quantized back
    /// to u8) before the float normalization. rvFACE keeps the bilinear
    /// result in f32 (`resize_bilinear_f32`) because our float resampler can
    /// differ from OpenCV's fixed-point u8 rounding by +-1 (see
    /// `rvface_core::image::resize_bilinear`); skipping the quantization
    /// avoids compounding that rounding, at the cost of sub-1/255-per-pixel
    /// input deltas versus Python.
    pub fn detect(&self, image: &Image, max_faces: usize) -> Result<Vec<Detection>, WeightsError> {
        let input = self.detector_input(image);
        let out = self.detector.forward(input)?;
        Ok(Self::pick_detections(&out, image, max_faces))
    }

    /// Async-read variant of [`Self::detect`] (see [`Self::analyze_async`]).
    pub async fn detect_async(
        &self,
        image: &Image,
        max_faces: usize,
    ) -> Result<Vec<Detection>, WeightsError> {
        let input = self.detector_input(image);
        let out = self.detector.forward_async(input).await?;
        Ok(Self::pick_detections(&out, image, max_faces))
    }

    /// Detector preprocessing: resize + normalize + NCHW tensor upload.
    fn detector_input(&self, image: &Image) -> Tensor<B, 4> {
        let [w, h] = SsdSlim320::<B>::IMAGE_SIZE;
        let hwc = resize_bilinear_f32(image, w, h);
        let chw = hwc_to_chw(&hwc, w, h, &DETECTOR_MEAN, &[DETECTOR_SCALE; 3]);
        Tensor::from_data(TensorData::new(chw, [1, 3, h, w]), &self.device)
    }

    /// Upstream postprocessing chain truncated to `max_faces`.
    fn pick_detections(
        out: &crate::detector::DetectorOutput,
        image: &Image,
        max_faces: usize,
    ) -> Vec<Detection> {
        let mut detections = postprocess(
            &out.confidences,
            &out.boxes,
            image.width,
            image.height,
            &PostprocessParams::default(),
        );
        detections.truncate(max_faces);
        detections
    }

    /// Landmark stage, exactly per `tools/fixtures/landmark-cunjian.notes.md`:
    /// 1.2x min-side square crop about the (floor-divided) box center, zero
    /// padding where the square leaves the image, 112x112 bilinear resize,
    /// BGR, `/255`; the [0, 1] outputs are mapped back through the padded
    /// square's frame into source-image pixels.
    fn landmarks(
        &self,
        image: &Image,
        detection: &Detection,
    ) -> Result<Option<Landmarks>, WeightsError> {
        let Some((out, crop)) = self.landmarks_raw(image, detection)? else {
            return Ok(None);
        };
        let raw: Vec<f32> = out.into_data().to_vec().expect("landmarks to host");
        Ok(Some(Self::reproject_landmarks(&raw, &crop)))
    }

    /// Async-read variant of [`Self::landmarks`] (see [`Self::analyze_async`]).
    async fn landmarks_async(
        &self,
        image: &Image,
        detection: &Detection,
    ) -> Result<Option<Landmarks>, WeightsError> {
        let Some((out, crop)) = self.landmarks_raw(image, detection)? else {
            return Ok(None);
        };
        let raw: Vec<f32> = out
            .into_data_async()
            .await
            .to_vec()
            .expect("landmarks to host");
        Ok(Some(Self::reproject_landmarks(&raw, &crop)))
    }

    /// Device-side landmark stage: crop + forward, output on the device.
    fn landmarks_raw(
        &self,
        image: &Image,
        detection: &Detection,
    ) -> Result<Option<(Tensor<B, 2>, LandmarkCrop)>, WeightsError> {
        let landmark = self
            .landmark
            .as_ref()
            .ok_or(WeightsError::MissingStage("landmark"))?;
        let Some(crop) = LandmarkCrop::compute(image, detection) else {
            return Ok(None);
        };
        let side = LANDMARK_INPUT;
        let hwc = resize_bilinear_f32(&crop.square, side, side);
        let chw = hwc_to_chw(&hwc, side, side, &[0.0; 3], &[LANDMARK_SCALE; 3]);
        let input = Tensor::from_data(TensorData::new(chw, [1, 3, side, side]), &self.device);
        let (out, _conv_features) = landmark.forward(input)?;
        Ok(Some((out, crop)))
    }

    /// Reproject [0, 1] square coordinates into source-image pixels
    /// (`BBox.reprojectLandmark`), using the padded square's true frame.
    fn reproject_landmarks(raw: &[f32], crop: &LandmarkCrop) -> Landmarks {
        let mut landmarks: Landmarks = [[0.0; 2]; 68];
        for (i, p) in landmarks.iter_mut().enumerate() {
            *p = [
                raw[2 * i] * crop.square.width as f32 + crop.origin_x as f32,
                raw[2 * i + 1] * crop.square.height as f32 + crop.origin_y as f32,
            ];
        }
        landmarks
    }
}

/// The zero-padded square landmark crop and its position in the source image.
struct LandmarkCrop {
    /// BGR square crop, image content copied in, borders zero-padded.
    square: Image,
    /// Source-image x of the square's left edge (may be negative).
    origin_x: i64,
    /// Source-image y of the square's top edge (may be negative).
    origin_y: i64,
}

impl LandmarkCrop {
    /// Ports the cunjian `test_batch_detections.py` crop math verbatim
    /// (Python `int()` truncation, `//` floor division, `cv2.copyMakeBorder`
    /// zero padding). Returns `None` for degenerate (sub-pixel) squares.
    fn compute(image: &Image, detection: &Detection) -> Option<Self> {
        let b = detection.bbox;
        let w = b.x2 - b.x1 + 1.0;
        let h = b.y2 - b.y1 + 1.0;
        // `size = int(min(w, h) * 1.2)`.
        let size = (w.min(h) * LANDMARK_CROP_SCALE) as i64;
        if size <= 0 {
            return None;
        }
        // `cx = x1 + w // 2` (floor division on the float box), square corner
        // offset by the integer `size // 2`.
        let cx = b.x1 + (w / 2.0).floor();
        let cy = b.y1 + (h / 2.0).floor();
        let half = (size / 2) as f32;
        let fx1 = cx - half;
        let fy1 = cy - half;
        let fx2 = fx1 + size as f32;
        let fy2 = fy1 + size as f32;

        // Clip to the image; the clipped-off amounts become zero padding
        // (`dx, dy, edx, edy`, each truncated like Python `int()`).
        let (iw, ih) = (image.width as f32, image.height as f32);
        let pad_l = (-fx1).max(0.0) as usize;
        let pad_t = (-fy1).max(0.0) as usize;
        let pad_r = (fx2 - iw).max(0.0) as usize;
        let pad_b = (fy2 - ih).max(0.0) as usize;
        let ix1 = fx1.max(0.0) as usize;
        let iy1 = fy1.max(0.0) as usize;
        let ix2 = fx2.min(iw) as usize;
        let iy2 = fy2.min(ih) as usize;
        if ix2 <= ix1 || iy2 <= iy1 {
            return None;
        }
        let (crop_w, crop_h) = (ix2 - ix1, iy2 - iy1);

        // Assemble crop + padding in one buffer; the landmark net was trained
        // on cv2 (BGR) crops, so swap channels while copying from RGB.
        let mut square = Image::zeros(crop_w + pad_l + pad_r, crop_h + pad_t + pad_b, 3);
        for y in 0..crop_h {
            for x in 0..crop_w {
                for c in 0..3 {
                    square.set(x + pad_l, y + pad_t, c, image.get(ix1 + x, iy1 + y, 2 - c));
                }
            }
        }
        Some(Self {
            square,
            origin_x: ix1 as i64 - pad_l as i64,
            origin_y: iy1 as i64 - pad_t as i64,
        })
    }
}

/// Interleaved HWC f32 -> normalized CHW f32: `out = (v - mean[c]) * scale[c]`
/// (the f32, per-channel-scale sibling of `rvface_core::image::to_chw_f32`).
fn hwc_to_chw(hwc: &[f32], w: usize, h: usize, mean: &[f32; 3], scale: &[f32; 3]) -> Vec<f32> {
    debug_assert_eq!(hwc.len(), w * h * 3);
    let mut out = vec![0.0f32; 3 * h * w];
    for y in 0..h {
        for x in 0..w {
            for (c, (m, s)) in mean.iter().zip(scale).enumerate() {
                out[c * h * w + y * w + x] = (hwc[(y * w + x) * 3 + c] - m) * s;
            }
        }
    }
    out
}

